#!/usr/bin/python3 -I
"""exc-guard — fail-closed shell-hook tartalék a `hooks.pre_tool_call`-hoz (#775, H-4, P5).

Külön processz. Minden művelet előtt friss, szerveroldali policyból dönt.
Ha a szerver nem érhető el, Kötött pálya érvényes; a user írható cache-e nem ad engedélyt.
Ha ez a program elszáll, a Hermes
(`fail_closed: true`) blokkolja a toolt. Az allow üres JSON, mert a nem-JSON
stdoutot a fail_closed szintén blokkolná.
"""
import importlib.util
import json
import os
import sys


def user_can_change(path):
    """Az aktuális user módosíthatja vagy törölheti-e a fájlt."""
    if os.name != "nt":
        info = os.stat(path)
        return info.st_uid != 0 or bool(info.st_mode & 0o022)
    # Windowson az st_uid mindig 0: a tényleges ACL-t kérdezzük meg egy írási megnyitással,
    # ami a tartalmat nem módosítja. A könyvtárban a fájl cseréje is módosítás.
    import ctypes
    from ctypes import wintypes
    create = ctypes.WinDLL("kernel32", use_last_error=True).CreateFileW
    create.restype = wintypes.HANDLE
    create.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    close = ctypes.windll.kernel32.CloseHandle
    share, open_existing, backup_semantics = 7, 3, 0x02000000
    checks = (
        (path, 0x40000000 | 0x00010000, 0),  # GENERIC_WRITE | DELETE
        (os.path.dirname(path), 0x2 | 0x40, backup_semantics),  # FILE_ADD_FILE | FILE_DELETE_CHILD
    )
    for target, access, flags in checks:
        handle = create(target, access, share, None, open_existing, flags, None)
        if handle not in (None, wintypes.HANDLE(-1).value):
            close(handle)
            return True
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    return False


def managed_gateway_url(managed_dir):
    path = os.path.join(managed_dir, "config.yaml")
    if user_can_change(path):
        raise ValueError("A céges konfiguráció rendszergazdai tulajdont és írásvédelmet igényel")
    with open(path, encoding="utf-8") as fh:
        in_model = False
        for line in fh:
            if line.strip() and not line.startswith((" ", "#")):
                in_model = line.strip() == "model:"
            if in_model and line.startswith("  base_url:"):
                return json.loads(line.split(":", 1)[1].strip())
    raise ValueError("Hiányzó céges modell-útvonal")


def plugin_dir():
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(here, "excellence-guard"),
        "/opt/excellence/hermes-plugins/excellence-guard",
    ]
    for folder in (here, os.path.join(here, "excellence-guard")):
        path = os.path.join(folder, "excellence_paths.py")
        if os.path.isfile(path):
            spec = importlib.util.spec_from_file_location("excellence_paths_guard", path)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            candidates.append(mod.plugin_dir())
            break
    for path in candidates:
        if os.path.isfile(os.path.join(path, "policy.py")):
            return path
    return None


def main():
    directory = plugin_dir()
    if not directory:
        sys.stderr.write("Az exc-guard nem találja a céges szabálymodult, ezért nem engedek műveletet.\n")
        return 2
    sys.path.insert(0, directory)
    import policy
    import runtime

    raw = sys.stdin.read()
    try:
        payload = json.loads(raw) if raw.strip() else {}
    except json.JSONDecodeError:
        sys.stderr.write("A céges ellenőrzés nem tudta elolvasni a kérést, ezért nem engedem.\n")
        return 2
    if not isinstance(payload, dict):
        payload = {}
    tool = payload.get("tool_name") or ""
    args = payload.get("tool_input") if isinstance(payload.get("tool_input"), dict) else {}
    home = os.environ.get("HERMES_HOME") or runtime.default_home()
    try:
        managed = runtime.managed_dir()
    except runtime.ManagedDirRedirected:
        sys.stdout.write(json.dumps({
            "action": "block",
            "message": "A Hermes nem a céges beállítást használja. Zárd be, és nyisd meg újra. Ha így is előjön, szólj a rendszergazdának.",
        }, ensure_ascii=False) + "\n")
        return 0
    try:
        token_helper = runtime.load_exc_token()
        origin = token_helper.read_profile(home)[0] if token_helper else None
        expected = origin + "/api/model-gateway/v1" if origin else None
        if not policy.is_excellence_route("excellence", managed_gateway_url(managed), expected):
            raise ValueError("A profil nem a céges modell-útvonalhoz tartozik")
        status, snapshot = runtime.fetch_snapshot(home)
    except Exception:
        status, snapshot = "down", None
    interpreted = {"kind": "snapshot", "snapshot": snapshot} if status == "ok" else {"kind": "revoked" if status == "revoked" else "bound"}
    decision = policy.decide_interpreted(interpreted, tool, args)
    sys.stdout.write(json.dumps(policy.hook_body(decision), ensure_ascii=False) + "\n")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.stderr.write("A céges ellenőrzés hibázott, ezért ezt a műveletet nem engedem.\n")
        sys.exit(2)

excellence-guard/policy.py:
"""Excellence Guard döntés (#775, spec §5.2, §9 R2/R4, D4).

Tiszta: nincs hálózat, nincs óra. A snapshot a V1-1 `GET /api/client-policy/snapshot`
alakja. Explicit tool-szabály (allow/approve/deny) előbb; ha nincs találat, a
képesség szintje dönt. Ismeretlen MCP-szerver company_only és plus_approved mellett
blokkol (U1). Hibás vagy hiányzó snapshot helyett a Kötött pálya preset.
"""
import os
import re
from urllib.parse import urlsplit

GUARD_VERSION = "0.1.0"
NOTICE = "Ez a munkatárs céges módban fut, a beszélgetéseid naplózásra kerülnek."
ASK = "Ha erre szükséged van, kérd a rendszergazdát."
OFFLINE_TTL_SECONDS = 3600
REVALIDATE_SECONDS = 15

# A V1-1 presetek képességszintjei (content_filter nélkül — az a gatewayé).
BOUND = {
    "code_execution": "denied",
    "local_files": "none",
    "browser": "denied",
    "web_search": "denied",
    "mcp_servers": "company_only",
    "skills": "approved_only",
    "local_memory": "excellence",
    "autonomous_run": "denied",
    "human_approval": "risky",
    "audit_depth": "plus_tool_results",
}
STANDARD = {
    **BOUND,
    "code_execution": "sandbox_only",
    "local_files": "read_only",
    "browser": "domain_allowlist",
    "web_search": "company_egress",
    "mcp_servers": "plus_approved",
    "autonomous_run": "audited",
    "audit_depth": "prompt_and_response",
}
FREE = {
    **BOUND,
    "code_execution": "local_free",
    "local_files": "project_write",
    "browser": "free",
    "web_search": "builtin",
    "mcp_servers": "plus_approved",
    "skills": "plus_own_audited",
    "local_memory": "local",
    "autonomous_run": "audited",
    "human_approval": "none",
    "audit_depth": "prompt_and_response",
}

_CODE = {"terminal", "process_manage", "execute_code", "close_terminal", "read_terminal"}
_FILE_READ = {"read_file", "search_files"}
_FILE_WRITE = {"write_file", "patch"}
_WEB = {"web_search", "web_extract", "x_search"}
_AUTO = {"delegate_task", "cronjob_manage"}
_SKILL_READ = {"skills_list", "skill_view"}
_SKILL_WRITE = {"skill_manage"}
_RULE_RANK = {"allow": 0, "approve": 1, "deny": 2}


class Decision:
    def __init__(self, action, message, capability=None, level=None):
        self.action = action  # allow | approve | block
        self.message = message
        self.capability = capability
        self.level = level

    def __repr__(self):
        return f"Decision({self.action!r}, {self.message!r})"


def bound_snapshot():
    return {
        "capabilities": dict(BOUND),
        "toolRules": [],
        "reasons": {key: {"source": "offline"} for key in BOUND},
        "policyVersion": "offline-bound",
    }


def snapshot_of(capabilities, tool_rules=(), version="test", source="user_preset"):
    return {
        "capabilities": dict(capabilities),
        "toolRules": list(tool_rules),
        "reasons": {key: {"source": source} for key in capabilities},
        "policyVersion": version,
    }


def sanitize_mcp_component(value):
    """Ugyanaz, mint a Hermes `sanitize_mcp_name_component`: nem [A-Za-z0-9_] → `_`."""
    return re.sub(r"[^A-Za-z0-9_]", "_", str(value or ""))


def mcp_server(tool_name):
    if not isinstance(tool_name, str) or not tool_name.startswith("mcp__"):
        return None
    server, sep, _tool = tool_name[5:].partition("__")
    return server if sep and server else None


def tool_origin(tool_name):
    return "mcp" if isinstance(tool_name, str) and tool_name.startswith("mcp__") else "local"


def company_servers():
    # Environment variables are controlled by the caller, not the company policy.
    return {"excellence"}


def _classify(tool_name):
    if tool_name.startswith("mcp__"):
        return "mcp_servers", "mcp"
    if tool_name in _CODE:
        return "code_execution", "code"
    if tool_name in _FILE_READ:
        return "local_files", "file_read"
    if tool_name in _FILE_WRITE:
        return "local_files", "file_write"
    if tool_name.startswith("browser_") or tool_name == "computer_use":
        return "browser", "browser"
    if tool_name in _WEB:
        return "web_search", "web"
    if tool_name == "memory":
        return "local_memory", "memory"
    if tool_name in _AUTO:
        return "autonomous_run", "autonomous"
    if tool_name in _SKILL_READ:
        return "skills", "skill_read"
    if tool_name in _SKILL_WRITE:
        return "skills", "skill_write"
    return None, "other"


def _pattern(pattern):
    body = ".*".join(re.escape(part) for part in str(pattern).split("*"))
    return re.compile(f"^{body}$")


def matching_rule(rules, tool_name):
    """Az összes illeszkedő szabály közül a legszigorúbb (tiltás nyer)."""
    found = None
    for rule in rules or []:
        pattern = rule.get("pattern") if isinstance(rule, dict) else None
        action = rule.get("action") if isinstance(rule, dict) else None
        if not pattern or action not in _RULE_RANK:
            continue
        if _pattern(pattern).match(tool_name):
            found = action if found is None or _RULE_RANK[action] > _RULE_RANK[found] else found
    return found


def _why(source):
    if source == "offline":
        return "Az Excellence szerver most nem elérhető, ezért a szigorúbb, kötött pályás szabály érvényes."
    if source == "agent_ceiling":
        return "Ez az asszisztens nem erre való."
    if source in ("user_preset", "user_override"):
        return "A te céges beállításod ezt nem engedi."
    return "A céges szabály ezt nem engedi."


def _lead(kind, level, tool_name):
    server = mcp_server(tool_name)
    if kind == "mcp":
        shown = server or "ismeretlen"
        return f"A(z) „{shown}” külső eszköz nincs a céges listán, ezért a(z) „{tool_name}” hívás nem fut le."
    if kind == "code" and level == "sandbox_only":
        return "A kódot csak a céges homokozóban futtathatod, a saját gépeden nem."
    if kind == "code":
        return "Ezzel az asszisztenssel nem futtathatsz parancsot vagy kódot a gépeden."
    if kind == "file_read" or (kind == "file_write" and level == "none"):
        return "Ezzel az asszisztenssel nem nyithatsz helyi fájlt."
    if kind == "file_write":
        if level == "project_write":
            return "A jóváhagyott projektmappa nincs megadva, ezért a helyi fájlmódosítást nem engedem."
        return "Fájlt olvashatsz, de írni vagy módosítani nem."
    if kind == "browser" and level == "company_cloud":
        return "A helyi böngésző nincs engedve. A céges böngésző ehhez az asszisztenshez még nem elérhető."
    if kind == "browser":
        if level == "domain_allowlist":
            return "A megengedett weboldalak céges listája nincs megadva, ezért a böngészőt nem engedem."
        return "A böngészőt ez a beállítás nem engedi."
    if kind == "web":
        return "A beépített webes keresés ki van kapcsolva."
    if kind == "memory":
        if level == "excellence":
            return "A céges memóriát az Excellence-eszközökön keresztül használd; a gépen tárolt memória ehhez az asszisztenshez nincs engedve."
        return "A helyi memória ki van kapcsolva."
    if kind == "autonomous":
        return "Önálló háttérfutást (másik asszisztens vagy időzített feladat) ez a beállítás nem enged."
    if kind == "skill_write":
        return "Új vagy módosított skillt ez a beállítás nem enged. Csak a jóváhagyott skillek használhatók."
    if kind == "skill_read":
        return "A jóváhagyott skillek ellenőrizhető céges listája még nem érhető el, ezért helyi skillt nem tölthetek be."
    return f"A(z) „{tool_name}” művelet nincs engedve."


def _block(kind, level, tool_name, source, capability):
    text = f"{_lead(kind, level, tool_name)} {_why(source)} {ASK}"
    return Decision("block", text, capability, level)


def _approve(tool_name, capability, level, because):
    return Decision(
        "approve",
        f"A(z) „{tool_name}” csak a jóváhagyásoddal fut le. {because}",
        capability,
        level,
    )


def _is_risky(kind):
    return kind in {"code", "file_write", "browser", "autonomous", "skill_write", "mcp"}


def _capability_action(kind, level, tool_name):
    if kind == "code":
        if level in ("denied", "sandbox_only"):
            return "block"
        if level == "local_with_approval":
            return "approve"
        return "allow"
    if kind == "file_read":
        return "block" if level == "none" else "allow"
    if kind == "file_write":
        return "allow" if level == "free" else "block"
    if kind == "browser":
        if level in ("denied", "company_cloud", "domain_allowlist"):
            return "block"
        return "allow"
    if kind == "web":
        return "block" if level in ("denied", "company_egress") else "allow"
    if kind == "memory":
        return "allow" if level == "local" else "block"
    if kind == "autonomous":
        return "block" if level == "denied" else "allow"
    if kind == "skill_write":
        return "block" if level == "approved_only" else "allow"
    if kind == "skill_read":
        if tool_name == "skill_view" and level == "approved_only":
            return "block"
        return "allow"
    if kind == "mcp":
        if level == "free":
            return "allow"
        server = mcp_server(tool_name)
        if server and sanitize_mcp_component(server) in company_servers():
            return "allow"
        return "block"
    # R2: ami nincs a katalógusban, az nincs engedve (explicit toolRules előbb nyer).
    return "block"


def decide(snapshot, tool_name, args=None):
    """allow / approve / block. Az args a későbbi útvonal-policyhoz van fenntartva (#748)."""
    del args  # v0: a szint és a tool-szabály dönt, nem a parancs szövege
    if not isinstance(tool_name, str) or not tool_name:
        return Decision("block", f"Nem látom, milyen művelet indulna, ezért nem engedem. {ASK}")
    caps = (snapshot or {}).get("capabilities")
    if not isinstance(caps, dict):
        snapshot = bound_snapshot()
        caps = snapshot["capabilities"]
    capability, kind = _classify(tool_name)
    level = caps.get(capability) if capability else None
    if capability and not isinstance(level, str):
        level = BOUND.get(capability)
    source = ((snapshot.get("reasons") or {}).get(capability) or {}).get("source") or "tenant_default"

    rule = matching_rule((snapshot or {}).get("toolRules"), tool_name)
    if rule == "deny":
        return Decision(
            "block",
            f"A(z) „{tool_name}” műveletet a céges szabály tiltja. {_why(source)} {ASK}",
            capability,
            level,
        )
    if rule == "approve":
        return _approve(tool_name, capability, level, "A céges szabály jóváhagyáshoz köti.")
    if rule == "allow":
        return Decision("allow", "", capability, level)

    action = _capability_action(kind, level, tool_name)
    if action == "block":
        return _block(kind, level, tool_name, source, capability)
    if action == "approve":
        because = "A beállítás ezt csak jóváhagyással engedi."
        if kind == "browser" and level == "domain_allowlist":
            because = "A megengedett oldalak listája nélkül nem engedem szabadon a böngészőt."
        return _approve(tool_name, capability, level, because)

    approval = caps.get("human_approval") or "risky"
    if approval == "always" or (approval == "risky" and _is_risky(kind)):
        return _approve(tool_name, capability, level, "A céges szabály a kockázatos műveletet jóváhagyáshoz köti.")
    return Decision("allow", "", capability, level)


def decide_interpreted(interpreted, tool_name, args=None):
    """A cache-értelmezés eredménye: revoked / bound / snapshot."""
    kind = (interpreted or {}).get("kind")
    if kind == "revoked":
        return Decision(
            "block",
            "Ehhez az asszisztenshez már nincs hozzáférésed, ezért semmilyen műveletet nem engedek. Kérd a rendszergazdát.",
        )
    if kind == "bound":
        return decide(bound_snapshot(), tool_name, args)
    return decide((interpreted or {}).get("snapshot"), tool_name, args)


def interpret_cache(state, now, offline_ttl=OFFLINE_TTL_SECONDS):
    """A lemezen lévő snapshot. Érvényes 1 óráig (D4), utána Kötött pálya. Visszavonás azonnal blokkol."""
    if not isinstance(state, dict):
        return {"kind": "bound"}
    if state.get("revoked"):
        return {"kind": "revoked"}
    cached_at = state.get("cachedAt")
    snap = state.get("snapshot")
    if not isinstance(cached_at, (int, float)) or not isinstance(snap, dict) or not isinstance(snap.get("capabilities"), dict):
        return {"kind": "bound"}
    if now - cached_at >= offline_ttl:
        return {"kind": "bound"}
    return {"kind": "snapshot", "snapshot": snap}


def hook_body(decision):
    """Hermes pre_tool_call / shell-hook válasz. Az allow `{}`: a fail_closed a nem-JSON stdoutot blokkolná."""
    if decision.action == "allow":
        return {}
    if decision.action == "approve":
        return {"action": "approve", "message": decision.message, "rule_key": "excellence-guard"}
    return {"action": "block", "message": decision.message}


def keep_content(depth, kind, content):
    """A szerver is eldobja, ami a mélységen kívül esik; ide se küldjük a promptot, ha nem kell."""
    rank = {"metadata": 0, "prompt_and_response": 1, "plus_tool_results": 2}
    need = 2 if kind == "tool_call" else 1
    if rank.get(depth, 0) < need:
        return None
    return content


def is_excellence_route(provider, base_url, expected_base_url=None):
    # Hermes named providers resolve to `custom` before execution middleware runs.
    if str(provider or "").strip().lower() not in {"excellence", "custom"}:
        return False
    def endpoint(value):
        url = urlsplit(str(value or "").strip())
        if url.scheme not in {"http", "https"} or not url.hostname or url.username is not None or url.password is not None or url.query or url.fragment:
            return None
        return url.scheme, url.hostname, url.port or (443 if url.scheme == "https" else 80), url.path.rstrip("/")
    try:
        actual, expected = endpoint(base_url), endpoint(expected_base_url)
        return expected is not None and actual == expected
    except ValueError:
        return False


PROVIDER_BLOCK = (
    "Ez a hívás nem a céges Excellence modellen menne, ezért megállítottam. "
    "Céges módban csak az Excellence modell használható, különben a beszélgetés kiesne a naplóból. "
    "Szólj a rendszergazdának, ha másik modell kell."
)

excellence-guard/runtime.py:
"""Snapshot-cache, audit-sor, heartbeat, plugin-életciklus (#775). Csak stdlib.

A shell-hook (`exc-guard`) ugyanezt a cache-fájlt olvassa, hálózat nélkül.
A managed-dir hash kanonikus alakja megegyezik a V1-8 `managedDirHash`-ével
(`excellence-managed-dir-v1`), hogy a szerver el tudja dönteni az eltérést.
"""
import hashlib
import importlib.util
from importlib.machinery import SourceFileLoader
import json
import logging
import os
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.request
import uuid
from types import SimpleNamespace

import policy

log = logging.getLogger("excellence_guard")

CACHE_FILE = ("excellence-guard", "snapshot.json")
QUEUE_FILE = ("excellence-guard", "audit-queue.jsonl")
MANAGED_FILES = ("config.yaml", ".env", "excellence-install-id")
HASH_VERSION = "excellence-managed-dir-v1"
MAX_CONTENT_CHARS = 200_000


def _load_paths():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "excellence_paths.py")
    spec = importlib.util.spec_from_file_location("excellence_paths_runtime", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


_paths = _load_paths()
ManagedDirRedirected = _paths.ManagedDirRedirected
DEFAULT_MANAGED_DIR = _paths.default_managed_dir()
TOKEN_HELPER_PATH = _paths.token_helper_path()
_lock = threading.Lock()


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def managed_dir_hash(files):
    body = "".join(f"{name}\n{sha256_bytes(files.get(name, b''))}\n" for name in MANAGED_FILES)
    body_bytes = f"{HASH_VERSION}\n{body}".encode()
    return sha256_bytes(body_bytes)


def hash_managed_dir(path):
    files = {}
    for name in MANAGED_FILES:
        try:
            with open(os.path.join(path, name), "rb") as fh:
                files[name] = fh.read()
        except OSError:
            files[name] = b""
    return managed_dir_hash(files)


def config_hash(home):
    try:
        with open(os.path.join(home, "config.yaml"), "rb") as fh:
            data = fh.read()
    except OSError:
        data = b"missing"
    return sha256_bytes(data)


def managed_dir():
    return _paths.resolve_managed_dir(os.environ.get("HERMES_MANAGED_DIR"), os.name == "nt")


def default_home():
    return _paths.default_home()


def reported_managed_dir_hash():
    """A heartbeat hash-e. Átirányított Windows-padlónál szándékosan nem egyezik a kiadottal."""
    try:
        return hash_managed_dir(managed_dir())
    except ManagedDirRedirected:
        return "redirected"


def _under(home, parts):
    return os.path.join(home, *parts)


def read_json(path):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return None


def write_json(path, payload):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f"{path}.{os.getpid()}.{uuid.uuid4().hex}"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        json.dump(payload, fh)
    os.replace(tmp, path)


def load_exc_token():
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(here, "..", "exc_token.py"),
        TOKEN_HELPER_PATH,
    ]
    for path in candidates:
        if not os.path.isfile(path):
            continue
        spec = importlib.util.spec_from_file_location("exc_token_guard", path, loader=SourceFileLoader("exc_token_guard", path))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    return None


def fetch_snapshot(home):
    """('ok', snapshot) | ('revoked', None) | ('down', None). A 401/403 visszavonás, nem D4."""
    if os.environ.get("EXC_GUARD_OFFLINE") == "1":
        return "down", None
    mod = load_exc_token()
    if mod is None:
        return "down", None
    try:
        token = mod.get_token(home)
        origin, _tenant, _agent = mod.read_profile(home)
    except mod.Fail as exc:
        text = str(exc)
        if "nincs hozzáférésed" in text or "Jelentkezz be" in text:
            return "revoked", None
        return "down", None
    req = urllib.request.Request(
        f"{origin}/api/client-policy/snapshot",
        headers={"Authorization": f"Bearer {token}"},
    )
    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            body = json.load(response)
        if isinstance(body, dict) and isinstance(body.get("capabilities"), dict):
            return "ok", body
        return "down", None
    except urllib.error.HTTPError as exc:
        if exc.code in (401, 403):
            return "revoked", None
        return "down", None
    except (urllib.error.URLError, OSError, ValueError):
        return "down", None


class SnapshotClient:
    def __init__(self, home, fetcher=None, now=time.time, revalidate=policy.REVALIDATE_SECONDS, offline_ttl=policy.OFFLINE_TTL_SECONDS):
        self.home = home
        self.fetcher = fetcher or (lambda: fetch_snapshot(home))
        self.now = now
        self.revalidate = revalidate
        self.offline_ttl = offline_ttl

    def path(self):
        return _under(self.home, CACHE_FILE)

    def read(self):
        return read_json(self.path())

    def refresh(self, force=False):
        now = self.now()
        state = self.read()
        fresh = (
            not force
            and isinstance(state, dict)
            and isinstance(state.get("cachedAt"), (int, float))
            and now - state["cachedAt"] < self.revalidate
            and isinstance(state.get("snapshot"), dict)
            and not state.get("revoked")
        )
        if fresh:
            return policy.interpret_cache(state, now, self.offline_ttl)
        status, snap = self.fetcher()
        if status == "ok":
            write_json(self.path(), {"cachedAt": now, "revoked": False, "snapshot": snap, "agentId": snap.get("agentId")})
            return {"kind": "snapshot", "snapshot": snap}
        if status == "revoked":
            write_json(self.path(), {"cachedAt": now, "revoked": True, "snapshot": None})
            return {"kind": "revoked"}
        return policy.interpret_cache(state, now, self.offline_ttl)


def _clip(value):
    if value is None:
        return None
    if isinstance(value, str):
        raw = value.encode("utf-8")
        if len(raw) <= MAX_CONTENT_CHARS:
            return value
        return raw[:MAX_CONTENT_CHARS].decode("utf-8", errors="ignore") + "… [levágva]"
    text = json.dumps(value, ensure_ascii=False, default=str)
    if len(text.encode("utf-8")) <= MAX_CONTENT_CHARS:
        return value
    return text.encode("utf-8")[:MAX_CONTENT_CHARS].decode("utf-8", errors="ignore") + "… [levágva]"


def build_event(snapshot, session_id, turn_id, kind, content, meta):
    depth = ((snapshot or {}).get("capabilities") or {}).get("audit_depth") or "metadata"
    kept = policy.keep_content(depth, kind, content)
    event = {
        "id": str(uuid.uuid4()),
        "sessionId": (session_id or "unknown")[:200],
        "kind": kind,
        "meta": meta or {},
    }
    if turn_id:
        event["turnId"] = str(turn_id)[:200]
    if kept is not None:
        event["content"] = _clip(kept)
    return event


def enqueue(home, event):
    path = _under(home, QUEUE_FILE)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    line = json.dumps(event, ensure_ascii=False)
    with _lock:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        with os.fdopen(fd, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")


def _read_queue(path):
    try:
        with open(path, encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError:
        return []
    events = []
    for line in lines:
        if not line.strip():
            continue
        try:
            events.append(json.loads(line))
        except ValueError:
            continue
    return events


def write_json_lines(path, events):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f"{path}.{os.getpid()}"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        for event in events:
            fh.write(json.dumps(event, ensure_ascii=False) + "\n")
    os.replace(tmp, path)


def flush_queue(home, post, limit=100):
    """post(events) → 'ok' | 'drop' | 'retry'. Az ok és a drop is kiveszi a feladott id-ket."""
    path = _under(home, QUEUE_FILE)
    with _lock:
        events = _read_queue(path)
    if not events:
        return 0
    batch = events[:limit]
    outcome = post(batch)
    if outcome == "retry":
        return 0
    sent = {event.get("id") for event in batch}
    with _lock:
        current = _read_queue(path)
        keep = [event for event in current if event.get("id") not in sent]
        if keep:
            write_json_lines(path, keep)
        elif os.path.exists(path):
            os.remove(path)
    return len(batch) if outcome == "ok" else 0


def post_json(url, token, payload, timeout=5):
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            raw = response.read()
            return response.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        return exc.code, {}
    except (urllib.error.URLError, OSError, ValueError):
        return 0, {}


def hermes_version():
    env = os.environ.get("HERMES_VERSION", "").strip()
    if env:
        return env[:200]
    try:
        out = subprocess.check_output(["hermes", "--version"], timeout=2, stderr=subprocess.STDOUT, text=True)
    except (OSError, subprocess.SubprocessError):
        return "unknown"
    line = (out or "").strip().splitlines()
    return (line[-1] if line else "unknown")[:200] or "unknown"


def synthetic_refusal(text):
    """OpenAI ChatCompletion-szerű objektum: a Hermes `normalize_response` a `.choices[0].message`-t olvassa."""
    message = SimpleNamespace(content=text, tool_calls=None, reasoning=None, reasoning_details=None, refusal=None)
    choice = SimpleNamespace(message=message, finish_reason="stop")
    return SimpleNamespace(id="excellence-guard-block", choices=[choice], usage=None, model="excellence")


class Guard:
    def __init__(self, home, client=None, now=time.time):
        self.home = home
        self.client = client or SnapshotClient(home, now=now)
        self.now = now
        self.sessions = set()
        self.noticed = set()
        self.decisions = {}
        self.interval = 60
        self._version = None

    def current(self, force=False):
        try:
            return self.client.refresh(force=force)
        except Exception:
            log.exception("snapshot")
            return policy.interpret_cache(self.client.read(), self.now(), policy.OFFLINE_TTL_SECONDS)

    def _audit_snapshot(self):
        interpreted = self.current()
        if interpreted.get("kind") == "snapshot":
            return interpreted["snapshot"]
        if interpreted.get("kind") == "bound":
            return policy.bound_snapshot()
        return {"capabilities": {"audit_depth": "metadata"}, "policyVersion": "revoked"}

    def note_session(self, session_id):
        if session_id:
            self.sessions.add(str(session_id)[:200])

    def pre_tool_call(self, tool_name=None, args=None, **kwargs):
        try:
            if not isinstance(args, dict):
                args = kwargs.get("tool_input") if isinstance(kwargs.get("tool_input"), dict) else {}
            # P4/NFR: visszavonás a következő hívásnál. Ha a Control Plane down, D4 cache marad.
            decision = policy.decide_interpreted(self.current(force=True), tool_name, args)
            call_id = kwargs.get("tool_call_id")
            if call_id:
                self.decisions[str(call_id)] = decision.action
            self.note_session(kwargs.get("session_id"))
            body = policy.hook_body(decision)
            return None if decision.action == "allow" else body
        except Exception:
            log.exception("pre_tool_call")
            return {"action": "block", "message": f"A céges ellenőrzés hibázott, ezért ezt a műveletet nem engedem. {policy.ASK}"}

    def post_tool_call(self, tool_name=None, args=None, result=None, **kwargs):
        try:
            call_id = str(kwargs.get("tool_call_id") or "")
            decision = self.decisions.pop(call_id, None)
            event = build_event(
                self._audit_snapshot(),
                kwargs.get("session_id"),
                kwargs.get("turn_id"),
                "tool_call",
                {"args": args, "result": result},
                {
                    "tool": tool_name,
                    "origin": policy.tool_origin(tool_name),
                    "status": kwargs.get("status"),
                    "decision": decision,
                },
            )
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("post_tool_call")

    def pre_llm_call(self, session_id=None, user_message=None, turn_id=None, **kwargs):
        try:
            self.note_session(session_id)
            event = build_event(self._audit_snapshot(), session_id, turn_id, "user_prompt", user_message, {})
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("pre_llm_call")
        return None

    def post_llm_call(self, session_id=None, assistant_response=None, turn_id=None, **kwargs):
        try:
            event = build_event(self._audit_snapshot(), session_id, turn_id, "final", assistant_response, {})
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("post_llm_call")

    def on_session_start(self, session_id=None, **kwargs):
        try:
            self.note_session(session_id)
            self.current(force=True)
            self.beat()
            if session_id and session_id not in self.noticed:
                self.noticed.add(session_id)
                sys.stderr.write(policy.NOTICE + "\n")
        except Exception:
            log.exception("on_session_start")

    def on_session_end(self, session_id=None, **kwargs):
        self.sessions.discard(session_id)

    def llm_execution(self, request=None, next_call=None, provider=None, base_url=None, **kwargs):
        token_helper = None
        try:
            token_helper = load_exc_token()
            expected_url = token_helper.read_profile(self.home)[0] + "/api/model-gateway/v1" if token_helper else None
            allowed = policy.is_excellence_route(provider, base_url, expected_url)
        except Exception as exc:
            log.exception("llm_execution")
            # A middleware fail-open: kivételre a Hermes továbbhívna. Inkább szintetikus elutasítás.
            # Az exc-token saját, érthető hibája (pl. nincs hozzárendelt asszisztens) ne modellhibának látsszon (#858).
            fail = getattr(token_helper, "Fail", ())
            return synthetic_refusal(str(exc) if isinstance(exc, fail) else policy.PROVIDER_BLOCK)
        if not allowed:
            return synthetic_refusal(policy.PROVIDER_BLOCK)
        # A kapu 180s után Open, ha a session lastSeenAt-je a háttérszál (másik folyamat) miatt kimarad.
        # Minden modellhívás előtt újra bejelentjük ezt a sessiont, ne csak az elsőt.
        sid = str(kwargs.get("session_id") or "")[:200]
        if sid:
            try:
                self.note_session(sid)
                self.beat()
            except Exception:
                log.exception("llm_execution heartbeat")
        if isinstance(request, dict):
            headers = dict(request.get("extra_headers") or {})
            for key, field in (("X-Excellence-Session", "session_id"), ("X-Excellence-Turn", "turn_id")):
                if kwargs.get(field):
                    headers = {name: value for name, value in headers.items() if name.lower() != key.lower()}
                    headers[key] = str(kwargs[field])[:200]
            # A Hermes a bare key_cmd jegyet 15 percig cache-eli, a gateway-JWT 10 perc. Friss token a kérésre.
            _, token = self._origin_and_token()
            if token:
                headers = {name: value for name, value in headers.items() if name.lower() != "authorization"}
                headers["Authorization"] = f"Bearer {token}"
            request = {**request, "extra_headers": headers}
        # A provider hibája a Hermes újrapróbálási/tömörítési útjára tartozik.
        return next_call(request)

    def _origin_and_token(self):
        mod = load_exc_token()
        if mod is None:
            return None, None
        try:
            return mod.read_profile(self.home)[0], mod.get_token(self.home)
        except Exception:
            return None, None

    def _flush_soon(self):
        if os.environ.get("EXC_GUARD_OFFLINE") == "1":
            return
        try:
            self.flush_audit()
        except Exception:
            log.exception("audit flush")

    def flush_audit(self):
        origin, token = self._origin_and_token()
        if not origin or not token:
            return 0

        def post(events):
            status, _body = post_json(f"{origin}/api/ai-audit/events", token, {"events": events})
            if 200 <= status < 300:
                return "ok"
            if status in (400, 413):
                return "drop"
            return "retry"

        return flush_queue(self.home, post)

    def beat(self):
        if os.environ.get("EXC_GUARD_OFFLINE") == "1":
            return
        origin, token = self._origin_and_token()
        if not origin or not token:
            return
        interpreted = self.current()
        if interpreted.get("kind") == "snapshot":
            version = interpreted["snapshot"].get("policyVersion") or "unknown"
        elif interpreted.get("kind") == "revoked":
            version = "revoked"
        else:
            version = "offline-bound"
        if self._version is None:
            self._version = hermes_version()
        payload = {
            "configHash": config_hash(self.home),
            "managedDirHash": reported_managed_dir_hash(),
            "policyVersion": str(version)[:200],
            "guardVersion": policy.GUARD_VERSION,
            "hermesVersion": self._version,
            "sessions": sorted(self.sessions)[:50],
        }
        status, body = post_json(f"{origin}/api/client-policy/heartbeat", token, payload)
        if status == 200 and isinstance(body, dict):
            interval = body.get("intervalSeconds")
            if isinstance(interval, int) and interval > 0:
                self.interval = interval

    def spawn(self):
        if os.environ.get("EXC_GUARD_DISABLE_BACKGROUND") == "1":
            return
        threading.Thread(target=self._loop, name="excellence-guard", daemon=True).start()

    def _loop(self):
        while True:
            time.sleep(max(self.interval, 15))
            try:
                self.current(force=True)
                self.beat()
                self.flush_audit()
            except Exception:
                log.exception("periodic")

excellence-guard/excellence_paths.py:
"""A céges telepítés útvonalai (#755).

A `machine-floor.ts` `CLIENT_COMMANDS.windows` ugyanezt a `C:\\ProgramData\\Excellence`
gyökeret írja a kiadott padlóba. Az `exc-token` `-I` mellett fut, ezért fájlútvonalról
tölti be ezt a modult, nem a `sys.path`-ról.
"""
import os

WINDOWS_ROOT = r"C:\ProgramData\Excellence"


class ManagedDirRedirected(Exception):
    """Windowson a felhasználói HERMES_MANAGED_DIR felülírná a gépszintű padlót."""


def default_managed_dir():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\hermes"
    return "/etc/hermes"


def token_helper_path():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\bin\exc-token"
    return "/opt/excellence/bin/exc-token"


def plugin_dir():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\hermes-plugins\excellence-guard"
    return "/opt/excellence/hermes-plugins/excellence-guard"


def default_home():
    """A Hermes alapértelmezett profilja: Windowson %LOCALAPPDATA%\\hermes, máshol ~/.hermes."""
    if os.name == "nt":
        return os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser(r"~\AppData\Local"), "hermes")
    return os.path.expanduser("~/.hermes")


def resolve_managed_dir(env_value, windows):
    """A Hermes által látott könyvtár. Windowson csak a céges hely érvényes.

    A felhasználói környezeti változó a gépszintűt felülírja, natív managed hely
    pedig nincs (U3). Az eltérő értéket nem követjük: a hook és a hash ugyanazt
    a könyvtárat nézi, az átirányítás fail-closed.
    """
    default = (WINDOWS_ROOT + r"\hermes") if windows else "/etc/hermes"
    if not env_value:
        return default
    if windows:
        if env_value.rstrip("\\/").lower() == default.rstrip("\\/").lower():
            return default
        raise ManagedDirRedirected(env_value)
    return env_value
